final cloudinary = Cloudinary.full(apiKey: key, apiSecret: secret, cloudName: name);
final response = await cloudinary.uploadResource(
  CloudinaryUploadResource(filePath: path, fileBytes: bytes, resourceType: CloudinaryResourceType.image, folder: 'myfolder', fileName: 'img.png'));
if (response.isSuccessful) print(response.secureUrl);
